import { ok, fail } from './result.js';
import { balanceDue } from './payments.js';
import { daysBetween, isValidDate } from './dates.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get overdue invoices as of a given date.
 * @param {Array} invoices list of invoices to filter
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {{ ok: true, value: Array } | { ok: false, error: string }}
 */
export function overdueInvoices(invoices, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) return fail('DATE_INVALID');

  // Filter for issued or partially_paid invoices with dueDate before asOf
  const overdue = invoices
    .filter(
      (inv) =>
        (inv.status === 'issued' || inv.status === 'partially_paid') &&
        inv.dueDate &&
        daysBetween(inv.dueDate, asOf) > 0,
    )
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);

  return { ok: true, value: overdue };
}

/**
 * Get VAT summary for invoices, grouped by VAT rate.
 * @param {Array} invoices list of invoices to summarize
 * @returns {{ ok: true, value: Array }}
 */
export function vatSummary(invoices) {
  const vatMap = {};

  // Filter for issued, partially_paid, or paid invoices
  const relevantInvoices = invoices.filter(
    (inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid',
  );

  // Process each line in each invoice
  for (const invoice of relevantInvoices) {
    for (const line of invoice.lines) {
      const rate = line.vatRate;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVat(line);

      if (!vatMap[rate]) {
        vatMap[rate] = { rate, base: 0, vat: 0 };
      }

      vatMap[rate].base += base;
      vatMap[rate].vat += vat;
    }
  }

  // Convert to array and sort by rate descending
  const summary = Object.values(vatMap).sort((a, b) => b.rate - a.rate);

  return { ok: true, value: summary };
}

/**
 * Calculate late fee for an invoice based on days overdue.
 * Late fee is 0.04% per day of the amount still due.
 * @param {{ dueDate: string, status: string }} invoice
 * @param {string} asOf date in YYYY-MM-DD format
 * @returns {number} late fee in cents
 */
export function lateFee(invoice, asOf) {
  // Validate asOf date
  if (!isValidDate(asOf)) return 0;

  // Check if invoice has a dueDate
  if (!invoice.dueDate) return 0;

  // Calculate days overdue
  const daysOverdue = Math.max(0, daysBetween(invoice.dueDate, asOf));

  // If not overdue, no late fee
  if (daysOverdue === 0) return 0;

  // Calculate late fee: 0.04% per day of the amount due
  const due = balanceDue(invoice);
  const fee = roundCents((due * 0.04 * daysOverdue) / 100);

  return Math.max(0, fee);
}

