test('lateFee accumulates correctly over time', () => {
  const inv = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-01-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }], // 10 * 9500 = 95000
  });

  assert.equal(inv.ok, true);
  const issued = issueInvoice(inv.value, []);
  assert.equal(issued.ok, true);
  // C-001 is gold tier: 95000 - 4750 (5% discount) = 90250, VAT 21% = 18952.5 ≈ 18952
  // Total = 95000 - 4750 + 18952 = 109202

  const fee1Day = lateFee(issued.value, '2025-01-30');
  const fee10Days = lateFee(issued.value, '2025-02-08');

  // Fees should increase with days
  assert(fee10Days > fee1Day);
  // 10 days should be approximately 10x the fee for 1 day
  assert(fee10Days > fee1Day * 8); // Allow for rounding
});

